"""Capture immutable opening state and link the measures into current guidance."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,subprocess
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).parent
def sha(raw):return hashlib.sha256(raw).hexdigest()
protected=list((ROOT/'prediction logs').glob('PREDICTION_LOG_COMBINED*.md'))
protected.append(ROOT/'research/canonical_ledger.jsonl')
for name in ('issued_research','issued','model_builds','src'):
    protected.extend(p for p in (ROOT/'research'/name).rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.suffix!='.pyc')
protected.extend(ROOT/name for name in ('research/improvement_register.json','research/verification/all_log_resolution_2026-10-05/improvement_proposals.json'))
opening=dict(created_utc=datetime.now(timezone.utc).isoformat(),head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT).decode().strip(),
             protected_files=[dict(path=p.relative_to(ROOT).as_posix(),bytes=p.stat().st_size,sha256=sha(p.read_bytes())) for p in sorted(set(protected))])
with (OUT/'opening.json').open('x',encoding='utf-8') as stream:json.dump(opening,stream,indent=2);stream.write('\n')
docs={'METHOD.md':'''\n## Fifteen experiment measures — current implementation\n\nAll fifteen source-bound retrospective proposals now have executable measurement definitions, immutable development locks, timed forecast capture and paired evaluation. [Measure register](research/experiment_measures.json), [protocols](research/experiments/protocols_v1.json) and [all next steps](research/experiments/NEXT_STEPS.md) define their exact scope. Hypotheses remain PROPOSED_NOT_TESTED; no candidate model, experiment result, forecast or qualification is created by implementing its measures. The experiment run store has separate lock/journal/result custody and is excluded from the living control inventory.\n''',
'CURRENT_RULES.md':'''\n## Fifteen experiments — measures implemented, results pending\n\nUse [the experiment measures and next steps](research/experiments/NEXT_STEPS.md) for all fifteen registered hypotheses. Freeze exact candidate/comparator artifacts, targets, future cohort, separate-pilot sample plan, declared dependence/adapter audits and justified acceptance tolerances before collecting the experimental forecasts. Capture real timestamps through `research.experiments.runner`; preserve all pending, void and abstention dispositions. Numerical measurement requirements govern experiment evaluation, never access to requested research or canonical logging. A statistical candidate-for-review result does not qualify or deploy a model. Existing qualification and source admission controls remain in force.\n''',
'SCORING_AND_VALIDATION.md':'''\n## Versioned fifteen-experiment measurement protocol\n\n[EXPERIMENT-MEASURES-1](research/experiments/protocols_v1.json) implements all fifteen source-bound hypotheses separately from the frozen certified pilot/scoring code. It measures exact contract Brier/log loss, per-target CRPS and 50/80/95-percent interval coverage/score, fixed-bin reliability and paired week-block uncertainty. Composite primary scores use fixed target weights and one score per event. Pushes remain outcome categories. Raw-unit distribution scores remain separate by target. Zero-probability observed outcomes retain an explicit infinite-loss flag; no silent clipping.\n\nThe fixed family is fifteen experiments: family alpha .05, per-comparison alpha .05/15, 60,000 paired week-block percentile replicates. Approximate inference requires a source-backed dependence audit. Sample planning uses a separate pilot with at least eight week blocks and a larger anticipated improvement than the minimum worthwhile threshold; the final cohort needs at least twenty blocks and its calculated numeric sample. No numbers or achieved power are invented for currently absent data. All acceptance tolerances remain unfilled until justified. [Full definitions, commands and next steps](research/experiments/NEXT_STEPS.md).\n\nEvery registry entry is MEASURES_IMPLEMENTED with experiment NOT_RUN_AT_REGISTRATION. Immutable locks pin evaluator code/runtime, model/input refs and cohort identities. Missing/invalid/pending observations block statistical decisions, and CANDIDATE_FOR_REVIEW never grants performance eligibility or changes an issued forecast. The original fifteen proposal texts and status remain unchanged.\n''',
'VERIFICATION_PROTOCOL.md':'''\n## Experiment-measure verification\n\nRun `py -3.14 -B -m research.experiments.runner verify` and include `research/experiments` in regression tests. The [catalog](research/experiment_measures.json) must cover all fifteen original hypotheses with preserved source hashes, fixed target/feature/measure definitions and explicit pending inputs. Test arithmetic independently and exercise overwrite, data leakage, period/provider, duplicate, pending-cohort, PMF and code/runtime-custody failures. Synthetic test success is never an experiment result. Runtime experiment stores use their own source/lock/journal/result hashes; original model builds, forecasts and ledger remain protected.\n''',
'CARD_AND_LOG_TEMPLATES.md':'''\n## Experiment forecasts and canonical cards\n\nThe [experiment protocol](research/experiments/NEXT_STEPS.md) defines separate development artifacts and actual-timestamp forecast journals. Creating a draft, power plan, experiment lock or measured result never allocates a P-ID or backfills a historical card. Requested game cards still use the canonical Part 6 workflow independently of calibration. Retain original `p`, ranking `q`, targets and issued versions; experiment probabilities are PMFs, and `q` is not scored as an event probability.\n''',
'README.md':'''\n## Fifteen proposed experiments — measurement implementation\n\nAll fifteen now have [source-bound measurement protocols](research/experiment_measures.json), an executable capture/evaluation workflow and [per-experiment next steps](research/experiments/NEXT_STEPS.md). Hypotheses are unrun; missing model, dataset, future-cohort and power/audit inputs remain explicit. Measurement tests do not establish predictive improvement.\n''',
'research/README.md':'''\n## Fifteen experiment measures and next steps\n\n[The measure register](experiment_measures.json) and [execution guide](experiments/NEXT_STEPS.md) cover all fifteen retrospective proposals. Run `py -3.14 -B -m research.experiments.runner verify` or `status` from the repository root. The CLI supplies template, source-backed power planning, immutable protocol freeze, real-time forecast capture and complete-cohort evaluation. It never creates canonical IDs or promotes models. Follow the guide for exact artifact fields, experiment-specific measures and every next step. Original proposal statuses remain PROPOSED_NOT_TESTED; zero actual experiments were run at registration.\n''',
'LEARNING_REGISTER.md':'''\n## Experiment implementation follow-through\n\nAll fifteen source-bound hypotheses retain their original text and PROPOSED_NOT_TESTED status. Their measures are now implemented in [the separate registry](research/experiment_measures.json); [next steps](research/experiments/NEXT_STEPS.md) specify adapters/features, comparator/candidate builds, separate pilot/power planning, future cohort locks, timed forecasts and terminal evaluation. Statistical completion and model qualification are later evidence-dependent transitions, never inferred from registration or unit tests.\n''',
'LEARNINGS_INDEX.md':'''\n- [All fifteen experiment measures and complete next steps](research/experiments/NEXT_STEPS.md): implemented development measurement infrastructure; hypothesis/model experiments remain unrun.\n''',
'CHANGELOG.md':'''\n## Fifteen experiment measures — 2026-10-05\n\nImplemented source-bound target/feature protocols, proper probability and distribution measures, paired block uncertainty, fifteen-comparison handling, separate-pilot power planning, immutable evaluator/model/runtime locks, actual-time capture and complete cohort accounting. Added per-experiment next steps and regression checks. Preserved all fifteen hypothesis texts, original forecasts, canonical IDs and model-build bytes. No new experiment result or qualification is asserted.\n'''}
changes=[]
for name,addition in docs.items():
    path=ROOT/name;raw=path.read_bytes();text=raw.decode('utf-8-sig')
    text=text.replace('CR-2026.10.05-I6','CR-2026.10.05-I7')
    if name=='METHOD.md':text=text.replace('CONTROL_MANIFEST_2026-10-05-6.md','CONTROL_MANIFEST_2026-10-05-7.md')
    text+=addition
    path.write_bytes(text.replace('\r\n','\n').replace('\n','\r\n').encode('utf-8'))
    changes.append(dict(path=name,before_sha256=sha(raw),after_sha256=sha(path.read_bytes())))
with (OUT/'document_changes.json').open('x',encoding='utf-8') as stream:json.dump(dict(files=changes),stream,indent=2);stream.write('\n')
print('Protected files',len(opening['protected_files']),'documents linked',len(changes))
